Model normalize(Model model) {
    Model result = ModelFactory.createDefaultModel();
    Map<String, Resource> generated = new HashMap<>();
    Function<RDFNode, RDFNode> canonical = node -> {
        String value = node.isURIResource() ? node.asResource().getURI()
                : node.isLiteral() ? node.asLiteral().getLexicalForm() : null;
        if (value != null && value.matches("http://oops\\.linkeddata\\.es/data/[0-9a-fA-F-]{36}")) {
            return generated.computeIfAbsent(value, key -> result.createResource());
        }
        if (node.isLiteral() && "http://www.w3.org/2001/XMLSchema#anyURI".equals(node.asLiteral().getDatatypeURI())) {
            return result.createResource(value);
        }
        return node;
    };
    model.listStatements().forEachRemaining(statement -> result.add(
            canonical.apply(statement.getSubject()).asResource(), statement.getPredicate(),
            canonical.apply(statement.getObject())));
    return result;
}
